package com.elektoryk.scan.model;
import org.json.*;import java.util.UUID;
public class EvidenceItem {public enum Category{BEFORE,HIDDEN_WORK,PANEL,TEST,FINISHED,OTHER}public String id=UUID.randomUUID().toString();public Category category=Category.HIDDEN_WORK;public String fileName="";public String mime="image/jpeg";public long createdAt=System.currentTimeMillis();public String roomId="";public int circuitNo;public String cutKey="";public String caption="";public JSONObject toJson() throws JSONException{JSONObject o=new JSONObject();o.put("id",id);o.put("category",category.name());o.put("fileName",fileName);o.put("mime",mime);o.put("createdAt",createdAt);o.put("roomId",roomId);o.put("circuitNo",circuitNo);o.put("cutKey",cutKey);o.put("caption",caption);return o;}public static EvidenceItem fromJson(JSONObject o){if(o==null)return null;EvidenceItem e=new EvidenceItem();e.id=o.optString("id",e.id);try{e.category=Category.valueOf(o.optString("category",Category.HIDDEN_WORK.name()));}catch(Exception ignored){}e.fileName=o.optString("fileName","");e.mime=o.optString("mime","image/jpeg");e.createdAt=o.optLong("createdAt",System.currentTimeMillis());e.roomId=o.optString("roomId","");e.circuitNo=o.optInt("circuitNo",0);e.cutKey=o.optString("cutKey","");e.caption=o.optString("caption","");return e;}}
